import{_ as i,o,c as e,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const a=JSON.parse('{"title":"2019-07-23 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-07-23 :: Crimson SeaStor OSD Weekly Meeting","date":"2019-07-23T00:00:00.000Z","updated":"2019-07-24T00:00:00.000Z","tags":["Ceph","BlueStore","RocksDB","CRimsonOS","兼容性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-07-23_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-07-23_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),s={name:"posts/2019/2019-07-23_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function n(r,l,_,g,p,S){return o(),e("div",null,[...l[0]||(l[0]=[t("<p>会议纪要：</p><p><strong>会议时间</strong>： 2019年7月23日 <strong>会议主题</strong>： Ceph存储系统相关技术讨论</p><p><strong>关键细节</strong>：</p><ul><li><strong>会议背景</strong>： 会议主要讨论了Ceph存储系统中BlueStore与CRimsonOS的兼容性、RocksDB的移植、性能优化以及功能扩展等议题。</li><li><strong>主要议题</strong>： <ul><li><strong>Ceph BlueStore 与 CRimsonOS 的兼容性</strong>： 讨论了将BlueStore移植到CRimsonOS的不同方案，包括代码修改、进程分离等，并分析了每种方案的优缺点。</li><li><strong>RocksDB 与 CRimsonOS 的兼容性</strong>： 讨论了如何将RocksDB移植到CRimsonOS，并分析了可能遇到的问题。</li><li><strong>Ceph存储系统性能优化</strong>： 讨论了如何优化Ceph存储系统的性能，包括I/O性能、内存使用率和网络带宽等。</li><li><strong>Ceph存储系统功能扩展</strong>： 讨论了如何扩展Ceph存储系统的功能，例如支持新的存储介质、提供更多存储服务等。</li></ul></li><li><strong>讨论的主要议题</strong>： <ul><li><strong>Ceph BlueStore 与 CRimsonOS 的兼容性</strong>： 包括方案一至四，以及它们各自的优势和劣势。</li><li><strong>RocksDB 与 CRimsonOS 的兼容性</strong>： 讨论了移植过程中可能遇到的问题。</li><li><strong>Ceph存储系统性能优化</strong>： 讨论了优化I/O性能、内存使用率和网络带宽等。</li><li><strong>Ceph存储系统功能扩展</strong>： 讨论了支持新的存储介质和提供更多存储服务。</li></ul></li><li><strong>决定的事项</strong>： <ul><li>继续讨论BlueStore与CRimsonOS的兼容性问题，并评估不同方案的可行性。</li><li>将RocksDB移植到CRimsonOS，并分析移植过程中可能遇到的问题。</li><li>优化Ceph存储系统的性能，并扩展其功能。</li></ul></li><li><strong>后续行动计划</strong>： <ul><li>继续讨论BlueStore与CRimsonOS的兼容性问题。</li><li>将RocksDB移植到CRimsonOS。</li><li>优化Ceph存储系统的性能。</li><li>扩展Ceph存储系统的功能。</li></ul></li></ul><p><strong>其他事项</strong>：</p><ul><li>讨论了Ceph存储系统与其他技术的兼容性。</li><li>讨论了Ceph存储系统的性能优化和功能扩展方案。</li></ul><p><strong>关键词</strong>：</p><ul><li>Ceph</li><li>BlueStore</li><li>CRimsonOS</li><li>RocksDB</li><li>性能优化</li><li>稳定性提升</li><li>功能扩展</li><li>共享内存</li><li>命名空间</li><li>链接器魔法</li></ul>",8)])])}const u=i(s,[["render",n]]);export{a as __pageData,u as default};
